import{_ as t,o,c as e,ag as r}from"./chunks/framework.DzGOF12C.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Essays/존 듀이 — 월요병가와 경험으로서의 예술.md","filePath":"philosophy/Essays/존 듀이 — 월요병가와 경험으로서의 예술.md"}'),_={name:"philosophy/Essays/존 듀이 — 월요병가와 경험으로서의 예술.md"};function s(p,a,i,h,n,l){return o(),e("div",null,[...a[0]||(a[0]=[r('<h3 id="서론" tabindex="-1">서론 <a class="header-anchor" href="#서론" aria-label="Permalink to &quot;서론&quot;">​</a></h3><p>현대 사회에서 예술은 종종 박물관이나 공연장과 같은 특정 공간에 갇힌, 일상과 분리된 고고한 대상으로 인식되는 경향이 있다. 이러한 인식은 예술이 삶의 본질적인 부분으로서 가지는 의미와 가치를 간과하게 만들며, 대중이 예술을 통해 얻을 수 있는 심미적 경험과 삶의 활력을 제한하는 구조적 문제를 내포한다. 전통적인 예술 개념이 일상과 분리된 고급 예술에 초점을 맞춤으로써, 예술의 민주화와 생활화를 강조하는 존 듀이 철학의 필요성이 더욱 부각된다. 존 듀이의 경험 중심 예술철학을 중심으로, 스텔라장의 노래 &#39;월요병가&#39;가 한 개인의 삶 속에서 어떻게 &#39;미적 경험&#39;으로 작용하며 세계와 소통하는 힘을 제공했는지 적으려고 한다. 이를 위해 존 듀이의 경험으로서의 예술을 이론적으로 살펴본 이후, 스텔라장 &#39;월요병가&#39;의 가사와 작가의 의도를 분석하고, 구체적인 음악 경험을 듀이의 예술철학 개념과 연결하여 해석한다. 특히, &#39;월요병가&#39;를 통해 예술이 삶과 직접적으로 연결될 수 있음을 깨닫고, 예술적 해석 능력을 기르게 된 과정을 다룬다.</p><h3 id="본론-1-—-듀이의-경험으로서의-예술" tabindex="-1">본론 1 — 듀이의 경험으로서의 예술 <a class="header-anchor" href="#본론-1-—-듀이의-경험으로서의-예술" aria-label="Permalink to &quot;본론 1 — 듀이의 경험으로서의 예술&quot;">​</a></h3><p>존 듀이는 예술을 특별한 영역이 아닌 &#39;경험&#39; 속에서 이해한다. 그는 &quot;경험은 예술의 근원이요 예술의 싹이다&quot;라고 강조하며, &quot;아무리 시시한 경험이라 하더라도 기쁨과 환희에 찬 인식이나 절망과 애통이 가득한 인식이 그 안에 포함되어 있다. 이것이 바로 미적 경험이다&quot;라고 설명한다. 이는 예술이 삶의 모든 순간, 심지어 고통스러운 경험 속에서도 발현될 수 있음을 의미한다. 전통적으로 예술이 특정 계층이나 전문가의 전유물로 여겨졌던 것과 달리, 듀이는 일상과 예술의 연결을 지향한다. 이처럼 예술의 범주를 확장함으로, 개인은 삶 속에서 예술적 가치를 발견하고, 이를 통해 세계와 더욱 깊이 있고 활력적인 관계를 맺을 수 있게 된다.</p><p>듀이의 철학에서 모든 경험이 예술이 되는 것은 아니며, 예술작품에서 경험은 &quot;일정한 형태와 구조를 가지고 통합되며 이 과정에서 경험은 충만하고 강렬한 형태를 띠게 된다.&quot; 이러한 개별 경험의 통합은 이성이 아니라 기쁨과 슬픔, 환희와 절망 등의 &#39;정서&#39;에 의해 이루어지며, 듀이는 이를 <strong>&#39;질성&#39;</strong> 개념으로 설명한다. &#39;질성&#39;은 경험의 통일성과 고유한 정서적 색채를 부여한다. 이 개념은 예술이 단순히 정보를 전달하거나 감정을 표출하는 것을 넘어, 분절된 경험들을 하나의 유기적이고 의미 있는 전체로 엮어내는 힘을 가짐을 보여준다.</p><p>듀이는 예술과 일상적 삶의 분리를 비판하며, 예술은 &quot;경험과 더불어 그리고 경험 속에서 만들어지는 것&quot;이라고 강조한다. 그는 &quot;예술은 가장 보편적인 형태의 언어, 즉 의사소통의 수단&quot;이라고 보며, &quot;예술작품이란 예술가의 경험과 관객의 경험이 미적 공동체를 형성하며 교감하는 장&quot;이라고 말한다. 예술은 개인의 내면을 성찰하게 할 뿐만 아니라, 사회적 소통과 사고의 폭을 넓히는 실천적인 기능을 수행한다.</p><h3 id="본론-2-—-월요병가-의-가사와-미적-경험" tabindex="-1">본론 2 — &#39;월요병가&#39;의 가사와 미적 경험 <a class="header-anchor" href="#본론-2-—-월요병가-의-가사와-미적-경험" aria-label="Permalink to &quot;본론 2 — &#39;월요병가&#39;의 가사와 미적 경험&quot;">​</a></h3><p>스텔라장의 &#39;월요병가&#39;는 &quot;지금 일요일이 거의 끝나가는데 내일이 오길 기다리는 일은 지옥 같아. 월요일을 만든 놈은 대체 누구. 가능만 하다면 병가를 내고 싶다. 머리가 너무 아프고 커피를 아무리 마셔도 졸리고 누워 있어야 할 것 같아요.&quot;와 같은 가사로 월요병이라는 현대인의 보편적인 일상적 고통과 무기력감을 직설적이고 익살적으로 표현한다. 또한 월요병을 &quot;유전 질환인 것 같아요. 우리 엄마 아빠 오빠 누나 동생 이모 다 걸려 있는 병이에요.&quot;라고 묘사하며, 개인의 고통이 가족 구성원 모두가 겪는 지병처럼 느껴지는 보편성을 강조한다.</p><p>&#39;월요병가&#39;는 개인의 사소하고 일상적인 고통인 월요병을 예술의 소재로 끌어올려, 이를 통해 현대인의 보편적인 삶의 애환과 무기력감에 대한 공감대를 형성한다. 이는 듀이가 강조하는 &#39;아무리 시시한 경험이라 하더라도 미적 경험이 될 수 있다&#39;는 점을 구체적으로 보여주며, 예술이 특별한 주제가 아닌 일상의 감정 속에서 그 가치를 찾을 수 있음을 증명한다. 이처럼 예술이 일상적이고 보편적인 감정을 다룸으로써, 대중은 예술을 자신과 동떨어진 것이 아닌 삶의 거울로서 인식하게 된다.</p><h3 id="본론-3-—-개인적-경험으로의-확장" tabindex="-1">본론 3 — 개인적 경험으로의 확장 <a class="header-anchor" href="#본론-3-—-개인적-경험으로의-확장" aria-label="Permalink to &quot;본론 3 — 개인적 경험으로의 확장&quot;">​</a></h3><p>&#39;월요병가&#39;는 예술이 삶과 직접적으로 연결될 수 있다는 걸 깨닫게 하는 경험으로 다가왔다. 단순한 음악 감상을 넘어, 일상적 고통과 감정에 깊이 상응하여 예술이 삶과 분리될 수 없음을 체감하게 한 결정적인 계기가 되었다. 이 경험은 듀이의 예술철학이 추구하는 예술의 생활화가 개인의 삶에서 어떻게 실질적으로 구현되는지를 보여주는 사례이다. 노래의 공감대는 자신의 감정을 예술 작품을 통해 확인하고 이해하도록 하였으며, 이는 예술이 삶의 동력으로 작용하는 인식의 전환으로 다가왔다.</p><p>이러한 경험 이후, 다른 예술 작품을 감상할 때도 작가의 의도를 통한 해석뿐만 아니라 다양한 삶을 통한 해석의 중요성을 일깨워주었다 — 예술 작품이 단순히 작가의 의도를 전달하는 매개체가 아니라, 관객 자신의 경험과 상호작용하며 새로운 의미를 창출하는 교감의 장이 될 수 있음을 의미한다. 이는 예술이 단순히 &#39;무엇을 말하는가&#39;를 넘어 &#39;어떻게 경험되는가&#39;에 초점을 맞추게 하며, 관객을 수동적 수용자에서 의미를 스스로 만드는 능동적 감상자로 변화시킨다.</p><p>또한, &#39;월요병가&#39;를 통해 보편적 감정에 공감하는 사람들과 미적 공동체를 형성하는 것이 중요함을 깨닫고, 나아가 대학 밴드 활동을 통해 예술이 가장 &#39;보편적인 형태의 언어&#39;임을 경험하였다. 일상에서 사용하는 언어는 대상을 정의 내리며 논리적 구조 속에서 사용되지만, 감각과 감정이 섞인 &#39;질성&#39;은 언어에서 온전히 드러나지 않는다. 밴드 활동을 통해 예술은 직접적인 경험의 전달을 통해 언어의 한계를 넘어선 보편적인 이해와 &#39;질성&#39;을 공유하는 효과적인 언어임을 몸소 느꼈다.</p><h3 id="결론" tabindex="-1">결론 <a class="header-anchor" href="#결론" aria-label="Permalink to &quot;결론&quot;">​</a></h3><p>&#39;월요병가&#39;는 개인의 일상적 행위와 사회적 활동을 통해 듀이 예술철학의 핵심인 일상성과 공동체성이 어떻게 유기적으로 연결되는지를 보여주는 사례이다. 이는 예술이 개인의 내면을 풍요롭게 할 뿐만 아니라, 같은 경험을 공유하는 타인과의 비언어적 소통을 가능하게 하여 사회적 유대감을 강화하고, 궁극적으로 삶의 활력과 의미를 확장하는 &#39;생활 속의 예술&#39;의 진정한 가치를 드러낸다.</p><p>존 듀이의 경험 중심 예술철학을 바탕으로 스텔라장 &#39;월요병가&#39;가 &#39;충만한 미적 경험&#39;을 제공하고, 이를 통해 삶과 예술의 본질적인 연결성을 깨닫게 하였다. &#39;월요병가&#39;는 일상적 고통을 &#39;질성&#39;으로 통합하고, 예술의 일상성과 공동체성을 느끼게 하며, 궁극적으로 세상을 받아들이는 힘을 기르는 계기가 되었다. 예술을 단순히 감상하거나 지식을 습득하는 대상으로 인식하기보다, 개인의 삶과 직접적으로 연결된 경험으로서의 예술을 강조함으로써, 더 많은 사람이 예술을 통해 고통을 극복하고 자아를 성장시키며 세계와 능동적으로 소통하는 힘을 얻을 수 있다.</p>',16)])])}const q=t(_,[["render",s]]);export{d as __pageData,q as default};
